// These files were captured from graphview before extraction, not generated by
// this implementation. The independent XML/literal assertions below and the
// existing graphview edit/export tests supplement this byte-equivalence oracle.
func TestSVGPreExtractionFixtures(t *testing.T) {
	for _, name := range []string{"right-rich", "left-plain", "negative-unsafe", "blank-long"} {
		t.Run(name, func(t *testing.T) {
			read := func(ext string) []byte {
				t.Helper()
				data, err := os.ReadFile(filepath.Join("testdata", "presentation", name+ext))
				if err != nil {
					t.Fatal(err)
				}
				return data
			}
			source, expected := read(".mindmap"), read(".svg")
			var meta struct {
				Bounds   Rect
				Warnings []string
			}
			if err := json.Unmarshal(read(".json"), &meta); err != nil {
				t.Fatal(err)
			}
			doc, issues, err := Parse(source, ParseOptions{})
			if err != nil {
				t.Fatal(err)
			}
			layout := Layout(doc, NativeLayoutOptions())
			if name == "negative-unsafe" {
				layout.Bounds = meta.Bounds
			} else if layout.Bounds != meta.Bounds {
				t.Fatalf("geometry changed: %+v want %+v", layout.Bounds, meta.Bounds)
			}
			warnings := make([]string, 0)
			for _, issue := range append(append(issues, layout.Issues...), PresentationIssues(doc)...) {
				warnings = append(warnings, issue.Message)
			}
			if !slices.Equal(warnings, meta.Warnings) {
				t.Fatalf("warning order/content changed: %q want %q", warnings, meta.Warnings)
			}
			result, err := ExportSVG(doc, layout, 0)
			if err != nil || !bytes.Equal(result, expected) || !utf8.Valid(result) {
				t.Fatalf("pre-extraction SVG differs (%d/%d bytes): %v", len(result), len(expected), err)
			}
			assertSVGXML(t, result)
			after, err := doc.Serialize(SerializeOptions{})
			if err != nil || !bytes.Equal(after, source) {
				t.Fatal("presentation mutated source", err)
			}
			t.Logf("exact retained SVG %s: %d bytes", name, len(result))
		})
	}
}

func TestSVGOutputBudgetAndNil(t *testing.T) {
	doc, _, err := Parse([]byte(`{"format":"levnote.mindmap","version":1,"root":{"id":"r","topic":"<&\"'🙂\n\n末"}}`), ParseOptions{})
	if err != nil {
		t.Fatal(err)
	}
	layout := Layout(doc, NativeLayoutOptions())
	expected, err := ExportSVG(doc, layout, 0)
	if err != nil || len(expected) == 0 {
		t.Fatal(err)
	}
	for _, cap := range []int{1, len(expected) - 1, -1} {
		data, err := ExportSVG(doc, layout, cap)
		if data != nil || !errors.Is(err, ErrSVGOutputLimit) {
			t.Fatalf("cap %d returned partial/success: %d %v", cap, len(data), err)
		}
	}
	for _, limit := range []int{len(expected), len(expected) + 1, 0, MaxSVGBytes, MaxSVGBytes + 1} {
		data, err := ExportSVG(doc, layout, limit)
		if err != nil || !bytes.Equal(data, expected) || len(data) != cap(data) {
			t.Fatalf("cap %d failed exact complete output: %v", limit, err)
		}
	}
	for _, doc := range []*Document{nil, {}} {
		if data, err := ExportSVG(doc, LayoutResult{}, 0); err == nil || data != nil {
			t.Fatal("unreadable document returned SVG")
		}
	}
	// A sticky writer refusal neither grows its count nor accepts later writes.
	w := svgWriter{limit: 3}
	w.text("ab")
	if n, err := w.Write([]byte("cd")); n != 0 || !errors.Is(err, ErrSVGOutputLimit) {
		t.Fatal("over-budget fragment partly written")
	}
	w.text("x")
	if w.written != 2 {
		t.Fatal("refused writer kept counting")
	}
}

func TestSVGOutputLimitEveryEscapedBoundary(t *testing.T) {
	source := []byte(`{"format":"levnote.mindmap","version":1,"root":{"id":"r","topic":"prefix<&>\"'\t\r\u0000🙂suffix\nnext"}}`)
	doc, _, err := Parse(source, ParseOptions{})
	if err != nil {
		t.Fatal(err)
	}
	layout := Layout(doc, NativeLayoutOptions())
	expected, err := ExportSVG(doc, layout, 0)
	if err != nil {
		t.Fatal(err)
	}
	// Independent XML spellings ensure the sweep really reaches every entity,
	// ordinary prefix/suffix and the next line, rather than only fixed syntax.
	escaped := "prefix&lt;&amp;&gt;&#34;&#39;&#x9;&#xD;�🙂suffix"
	if !bytes.Contains(expected, []byte(escaped)) || !reflect.DeepEqual(svgText(t, expected), []string{"prefix<&>\"'\t\r�🙂suffix", "next"}) {
		t.Fatalf("escaped fixture does not exercise the intended boundaries: %s", expected)
	}
	for limit := 1; limit < len(expected); limit++ {
		data, err := ExportSVG(doc, layout, limit)
		if data != nil || !errors.Is(err, ErrSVGOutputLimit) {
			t.Fatalf("public cap %d/%d: output=%d err=%v", limit, len(expected), len(data), err)
		}
		for _, fill := range []bool{false, true} {
			writer := svgWriter{limit: limit}
			var backing []byte
			if fill {
				// A suffix outside the admitted slice plus unwritten bytes inside
				// it detect partial-fragment copies and writes after refusal.
				backing = bytes.Repeat([]byte{0xa5}, limit+8)
				writer.data = backing[:limit:limit]
			}
			if err := emitSVG(&writer, doc, layout); !errors.Is(err, ErrSVGOutputLimit) || writer.err != ErrSVGOutputLimit || writer.written > limit {
				t.Fatalf("writer cap %d fill=%v: written=%d err=%v retained=%v", limit, fill, writer.written, err, writer.err)
			}
			written := writer.written
			writer.text("later")
			writer.printf("%s", "later")
			writeSVGMultilineText(&writer, 0, 0, "<&", "#000", 14, true)
			if n, err := writer.Write([]byte("later")); n != 0 || err != ErrSVGOutputLimit || writer.written != written {
				t.Fatalf("writer not terminal after refusal at cap %d fill=%v", limit, fill)
			}
			if fill && (!bytes.Equal(backing[:written], expected[:written]) || !bytes.Equal(backing[written:], bytes.Repeat([]byte{0xa5}, len(backing)-written))) {
				t.Fatalf("partial fragment or post-refusal write at cap %d", limit)
			}
		}
	}
	for _, limit := range []int{len(expected), len(expected) + 1} {
		data, err := ExportSVG(doc, layout, limit)
		if err != nil || !bytes.Equal(data, expected) {
			t.Fatalf("complete boundary %d changed successful output: %v", limit, err)
		}
	}
	t.Logf("all %d positive insufficient caps: public nil/sentinel plus count/fill sticky writes; complete=%d bytes", len(expected)-1, len(expected))
}

func TestSVGIndependentGeometryEscapingAndPaint(t *testing.T) {
	source := []byte(`{"format":"levnote.mindmap","version":1,"root":{"id":"r","topic":"<&\"'\t🙂\r\n\n尾","icons":["⭐","custom<&","⭐"],"tags":["","甲<&"],"style":{"color":" ReBeccAPurple ","border":"url(https://invalid)"},"collapsed":true,"image":{"url":"https://invalid/a.png","width":40,"height":40},"children":[{"id":"a","topic":"隐藏"}]}}`)
	doc, _, err := Parse(source, ParseOptions{})
	if err != nil {
		t.Fatal(err)
	}
	layout := Layout(doc, NativeLayoutOptions())
	layout.Bounds = Rect{X: -210, Y: -150, Width: 520, Height: 340}
	data, err := ExportSVG(doc, layout, 0)
	if err != nil {
		t.Fatal(err)
	}
	for _, literal := range []string{
		`viewBox="-234 -174 568 388" width="568" height="388"`,
		`<rect x="-234" y="-174" width="568" height="388" fill="#ffffff"/>`,
		`fill="#663399"`, `stroke="#33766c"`,
		`custom&lt;&amp; ⭐ &lt;&amp;&#34;&#39;&#x9;🙂&#xD;`, `>+</text>`, `>图</text>`,
	} {
		if !bytes.Contains(data, []byte(literal)) {
			t.Fatalf("missing independent SVG literal %q: %s", literal, data)
		}
	}
	if bytes.Contains(data, []byte("invalid")) || bytes.Contains(data, []byte("隐藏")) {
		t.Fatal("hidden child or external paint/reference leaked to SVG")
	}
	labels := svgText(t, data)
	if !reflect.DeepEqual(labels, []string{"⭐ custom<& ⭐ <&\"'\t🙂\r", "", "尾 [ · 甲<&]"}) {
		t.Fatalf("decoded Unicode/blank/duplicate label mismatch: %q", labels)
	}
	// Nonpositive geometry keeps the previous fallback dimensions.
	layout.Bounds = Rect{}
	data, err = ExportSVG(doc, layout, 0)
	if err != nil || !bytes.Contains(data, []byte(`viewBox="-24 -24 368 248"`)) {
		t.Fatal("fallback dimensions changed", err)
	}
}

func assertSVGXML(t *testing.T, data []byte) {
	t.Helper()
	decoder := xml.NewDecoder(bytes.NewReader(data))
	for {
		_, err := decoder.Token()
		if err == io.EOF {
			return
		}
		if err != nil {
			t.Fatal(err)
		}
	}
}

func svgText(t *testing.T, data []byte) []string {
	t.Helper()
	decoder := xml.NewDecoder(bytes.NewReader(data))
	var texts []string
	for {
		token, err := decoder.Token()
		if err == io.EOF {
			return texts
		}
		if err != nil {
			t.Fatal(err)
		}
		if start, ok := token.(xml.StartElement); ok && start.Name.Local == "tspan" {
			var value string
			if err := decoder.DecodeElement(&value, &start); err != nil {
				t.Fatal(err)
			}
			texts = append(texts, value)
		}
	}
}

// Moved with the multiline helper from graphview. Public ExportSVG bounds each
// label, while this helper-level oracle keeps its long escaping behavior exact.
func TestLongSVGTextPreservesMultilineUnicode(t *testing.T) {
	long := strings.Repeat("中文🙂<&", 32768)
	count := svgWriter{limit: MaxSVGBytes}
	writeSVGMultilineText(&count, 0, 0, long+"\n\n尾行", "#123456", 14, true)
	fill := svgWriter{limit: count.written, data: make([]byte, count.written)}
	writeSVGMultilineText(&fill, 0, 0, long+"\n\n尾行", "#123456", 14, true)
	if count.err != nil || fill.err != nil || fill.written != count.written {
		t.Fatal("long multiline writer failed", count.err, fill.err)
	}
	texts := svgText(t, fill.data)
	if !reflect.DeepEqual(texts, []string{long, "", "尾行"}) {
		t.Fatal("long export dropped/split Unicode or empty lines")
	}
}

var splitLineResult []string

func BenchmarkSVGSplitLongLabel(b *testing.B) {
	for _, size := range []int{64 * 1024, 1024 * 1024} {
		b.Run(svgNumber(float64(size)), func(b *testing.B) {
			value := strings.Repeat("x", size) + "\n中文🙂"
			b.SetBytes(int64(len(value)))
			b.ReportAllocs()
			b.ResetTimer()
			for i := 0; i < b.N; i++ {
				splitLineResult = splitLines(value)
			}
		})
	}
}
